import type { TaskBoard, TaskView } from "./tasks";

/**
 * The now panel's one rule (task-system design section 10, P4): which
 * board rows the panel shows and under which group. The panel on the
 * right rail is a Tier-2 frame that paints the board it subscribes to;
 * what the HOST needs from the same rule is only whether there is anything
 * to show (visibility is data - a rail with nothing docked stays empty),
 * and the record card's meta line names a row's state in the same words.
 *
 * Five groups, in the order the panel lists them:
 *
 * - `waiting`  - needs you: an open decision card on it, a captain hold, or
 *                a dead blocker. Rows shown by default.
 * - `underway` - active, whatever its activity. Rows shown by default.
 * - `to-land`  - delivered: finished work whose worktree is still there.
 * - `charted`  - open: planned work, ready, blocked, held, or on request.
 * - `landed`   - done work within the board's recent window.
 *
 * Deliberately outside the panel: dropped rows (history, one detail read
 * away), and closed question/operation rows - an answered question or a
 * finished fleet operation is not landed work, and every plain captain turn
 * files one (P1), so listing them would bury the rail in chit-chat.
 *
 * The frame script (src/renderer/src/plugins/builtin/now/now.frame.js)
 * carries the same rule in its own realm - it cannot import this module -
 * and tests/e2e/now-panel.spec.ts pins that the two agree.
 */

export const NOW_GROUPS = ["waiting", "underway", "to-land", "charted", "landed"] as const;
export type NowGroup = (typeof NOW_GROUPS)[number];

/** The group's label as the panel prints it. */
export const NOW_GROUP_LABELS: Record<NowGroup, string> = {
  waiting: "waiting on you",
  underway: "underway",
  "to-land": "to land",
  charted: "charted",
  landed: "landed · 7d",
};

export function nowGroupOf(task: TaskView): NowGroup | null {
  switch (task.status) {
    case "dropped":
      return null;
    case "done":
      return task.kind === "work" ? "landed" : null;
    case "delivered":
      return task.flags.needsYou ? "waiting" : "to-land";
    case "active":
      return task.flags.needsYou ? "waiting" : "underway";
    case "open":
      return task.flags.needsYou ? "waiting" : "charted";
  }
}

/** Whether the board gives the now panel anything to show. */
export function nowPanelHasRows(board: Pick<TaskBoard, "tasks">): boolean {
  return board.tasks.some((task) => nowGroupOf(task) !== null);
}

/**
 * A row's state in one or two words, for the record card's meta line
 * (`FM3K-12 · underway`). The panel's vocabulary, so the card and the rail
 * never disagree about what a task is doing.
 */
export function taskStatusWord(task: TaskView): string {
  const group = nowGroupOf(task);
  if (group === "waiting") return NOW_GROUP_LABELS.waiting;
  if (task.status === "dropped") return task.closedReason === "failed" ? "failed" : "dropped";
  if (task.status === "done") return task.closedReason === "answered" ? "answered" : "done";
  if (task.status === "delivered") return NOW_GROUP_LABELS["to-land"];
  if (task.status === "active") {
    if (task.activity === "idle") return "idle";
    if (task.activity === "interrupted") return "interrupted";
    return NOW_GROUP_LABELS.underway;
  }
  if (task.flags.blocked) return "blocked";
  if (task.flags.held) return "held";
  return task.startPolicy === "on-request" ? "on request" : NOW_GROUP_LABELS.charted;
}

