 * App-raised singleton decisions (auth, flagship ladder) re-raise on their
 * own triggering events; parking them for a day would resurface stale
 * questions, so Later keeps its pre-R1 dismiss semantics for exactly these.
 */
function isSingletonDecision(cardId: string): boolean {
  return (
    cardId === "card-fm-flagship-move" ||
    cardId === "card-fm-no-headroom" ||
    cardId === "card-fm-auth" ||
    cardId.startsWith("card-auth-")
  );
}

/** An active row a previous process left idle or interrupted: steerable by resume. */
function isResumable(record: TaskRecord): boolean {
  return (
    record.status === "active" && (record.activity === "idle" || record.activity === "interrupted")
  );
}

/** The record's state in the words the tools and refusals use. */
function describeStatus(record: TaskRecord): string {
  if (record.status === "open") return "queued";
  if (record.status === "active") return record.activity ?? "active";
  if (record.status === "delivered") return "finished";
  return record.closedReason ?? record.status;
}

/** Name the crewmate and task on its turn_failed before it reaches the feed. */
function enrichEvent(task: TaskRuntime, event: FmEvent): FmEvent {
  if (event.type !== "turn_failed") return event;
  return { ...event, crewmate: task.crewmate, title: task.title };
}

