import { execFile } from "node:child_process";
import { existsSync } from "node:fs";
import { CI_FRESHNESS_MS } from "../pi/cardLint";
import type { TaskService } from "../tasks/taskService";
import type { RepoRegistry } from "../workspace/repoRegistry";

/**
 * check_pr_ci's host side (contract v1, spec section 1.4 + G-1): the
 * standing CI rule as typed code instead of prompt-steered bash. Resolves a
 * task's repo and branch, finds its open PR, and reports every check on the
 * PR head SHA; overall green requires every check completed AND successful
 * (PR 8's rule, verbatim). Every result is recorded on the task's delivery
 * facts with a timestamp (task-system P0) - that record powers the
 * emit_card land-gate (G-1) and survives a restart; the checked PR head
 * and cwd the merge needs stay in memory for the click that follows.
 *
 * Fail soft by contract: task unknown, repo local-only, no PR, and gh
 * failures all return as explanatory tool text, never a throw.
 */

export type PrCiOverall = "green" | "red" | "pending" | "no-pr";

export type RunGh = (args: string[], cwd: string) => Promise<{ stdout: string; stderr: string }>;

const GH_TIMEOUT_MS = 30_000;

const defaultRunGh: RunGh = (args, cwd) =>
  new Promise((resolve, reject) => {
    execFile(
      "gh",
      args,
      { cwd, timeout: GH_TIMEOUT_MS, maxBuffer: 4 * 1024 * 1024 },
      (error, stdout, stderr) => {
        // gh pr checks exits non-zero for failing or pending checks while
        // still printing the report; JSON on stdout wins over the exit code.
        // Every other gh operation is strict, especially the irreversible
        // merge command.
        if (error && (args[1] !== "checks" || !stdout.trim())) {
          reject(new Error(stderr.trim() || error.message));
          return;
        }
        resolve({ stdout, stderr });
      },
    );
  });

/** gh pr checks --json state values that mean a completed, successful check. */
const GREEN_STATES = new Set(["SUCCESS"]);
/** States that are terminal and not success: the run is red now. */
const RED_STATES = new Set([
  "FAILURE",
  "ERROR",
  "CANCELLED",
  "TIMED_OUT",
  "ACTION_REQUIRED",
  "STARTUP_FAILURE",
  "STALE",
]);

function describeState(state: string): string {
  if (GREEN_STATES.has(state)) return "completed / success";
  if (RED_STATES.has(state)) return `completed / ${state.toLowerCase()}`;
  if (state === "SKIPPED" || state === "NEUTRAL") return `completed / ${state.toLowerCase()}`;
  return "in_progress / -";
}

type CheckedPr = { number: number; url: string; headRefOid: string; cwd: string };

export class PrCiService {
  /** The checked PR (head SHA, cwd) per task, for the merge that follows a check. */
  private readonly checked = new Map<string, CheckedPr>();
  private readonly runGh: RunGh;

  constructor(
    private readonly options: {
      tasks: TaskService;
      repos: RepoRegistry;
      runGh?: RunGh;
      now?: () => number;
    },
  ) {
    this.runGh = options.runGh ?? defaultRunGh;
  }

  /** The recorded CI reading on the task's delivery facts. */
  private reading(taskId: string): { overall: PrCiOverall; at: number } | undefined {
    const delivery = this.options.tasks.get(taskId)?.delivery;
    if (!delivery?.ci || delivery.ciAt === undefined) return undefined;
    return { overall: delivery.ci, at: delivery.ciAt };
  }

  /** G-1: a green result at most CI_FRESHNESS_MS old exists for this task. */
  freshGreen(taskId: string): boolean {
    const record = this.reading(taskId);
    if (!record) return false;
    return record.overall === "green" && this.now() - record.at <= CI_FRESHNESS_MS;
  }

  /** The last known state in refusal-copy words. */
  stateText(taskId: string): string {
    const record = this.reading(taskId);
    if (!record) return "unknown - check_pr_ci has not been called for it";
    if (record.overall === "green" && this.now() - record.at > CI_FRESHNESS_MS) {
      return "stale - the last green check is older than 5 minutes";
    }
    return record.overall;
  }

  /** The check_pr_ci tool body: typed CI status on the task's PR head SHA. */
  async check(taskId: string): Promise<string> {
    const record = this.options.tasks.get(taskId.trim());
    if (!record) {
      return `Unknown task "${taskId}". Use a task id from crew_status.`;
    }
    if (!record.branch) {
      return `Task ${record.id} has no branch yet (still queued); there is no PR to check.`;
    }
    const repo = record.repoId ? this.options.repos.get(record.repoId) : undefined;
    if (record.repoId && !repo) {
      return `Task ${record.id}'s repository is no longer registered; cannot check CI.`;
    }
    if (repo && repo.delivery === "local-only") {
      return `Repository ${repo.name} is local-only; its work never has a PR, so there is no CI to check.`;
    }
    const cwd =
      record.worktreeDir && existsSync(record.worktreeDir)
        ? record.worktreeDir
        : (repo?.path ?? record.repoDir);
    if (!cwd || !existsSync(cwd)) {
      return `Task ${record.id}'s working directory is gone; cannot check CI.`;
    }
    try {
      const list = await this.runGh(
        [
          "pr",
          "list",
          "--head",
          record.branch,
          "--state",
          "open",
          "--json",
          "number,url,headRefOid",
          "--limit",
          "1",
        ],
        cwd,
      );
      const prs = JSON.parse(list.stdout || "[]") as {
        number: number;
        url: string;
        headRefOid: string;
      }[];
      const pr = prs[0];
      if (!pr) {
        this.record(record.id, "no-pr");
        return `overall: no-pr\nNo open PR found for branch ${record.branch}.`;
      }
      const checks = await this.runGh(
        ["pr", "checks", String(pr.number), "--json", "name,state"],
        cwd,
      );
      const parsed = JSON.parse(checks.stdout || "[]") as { name: string; state: string }[];
      const overall = overallOf(parsed);
      this.record(record.id, overall, { ...pr, cwd });
      const lines = parsed.map((check) => `- ${check.name}: ${describeState(check.state)}`);
      return [
        `PR #${pr.number} ${pr.url} head ${pr.headRefOid}`,
        `overall: ${overall}`,
        ...(parsed.length > 0 ? lines : ["- no checks reported on the head SHA"]),
      ].join("\n");
    } catch (caught) {
      const message = caught instanceof Error ? caught.message : String(caught);
      return `Could not check CI for task ${record.id}: ${message}`;
    }
  }

  /**
   * Native Merge PR semantics. Re-check the complete head check suite at the
   * moment of the click, then ask GitHub to merge that exact open PR.
   */
  async merge(taskId: string): Promise<{ ok: boolean; text: string }> {
    // A stale earlier success must never survive a failed re-check.
    this.checked.delete(taskId);
    const status = await this.check(taskId);
    const reading = this.reading(taskId);
    const pr = this.checked.get(taskId);
    if (reading?.overall !== "green" || !pr) {
      return {
        ok: false,
        text: `PR merge blocked: CI is not fully green. ${status}`,
      };
    }
    try {
      await this.runGh(
        ["pr", "merge", String(pr.number), "--merge", "--match-head-commit", pr.headRefOid],
        pr.cwd,
      );
      return {
        ok: true,
        text: `Merged PR #${pr.number} on GitHub. ${pr.url}`,
      };
    } catch (caught) {
      const message = caught instanceof Error ? caught.message : String(caught);
      return { ok: false, text: `PR merge blocked: ${message}` };
    }
  }

  /**
   * Record the reading on the task: the CI verdict and its time, plus the
   * PR facts when one exists. A newly seen PR is a `pr_opened` event; every
   * read is a `ci` event on the timeline.
   */
  private record(taskId: string, overall: PrCiOverall, pr?: CheckedPr): void {
    const at = this.now();
    const task = this.options.tasks.get(taskId);
    if (pr) {
      this.checked.set(taskId, pr);
    } else {
      this.checked.delete(taskId);
    }
    if (!task) return;
    const known = task.delivery?.prNumber;
    if (pr && known !== pr.number) {
      this.options.tasks.recordDelivery(
        taskId,
        { prUrl: pr.url, prNumber: pr.number },
        { kind: "pr_opened", text: `PR #${pr.number} ${pr.url}`, feed: true },
      );
    }
    this.options.tasks.recordDelivery(
      taskId,
      { ci: overall, ciAt: at },
      {
        kind: "ci",
        text: pr ? `CI ${overall} on PR #${pr.number} head ${pr.headRefOid}` : `CI ${overall}`,
      },
    );
  }

  private now(): number {
    return this.options.now?.() ?? Date.now();
  }
}

/**
 * The rule verbatim from PR 8: green only when EVERY check is completed and
 * successful. Any terminal non-success is red; anything else (pending,
 * queued, skipped, neutral) blocks green without being red. A PR with zero
 * checks reads green - a repo with no CI must still be landable - and the
 * result text says so explicitly.
 */
export function overallOf(checks: { state: string }[]): PrCiOverall {
  if (checks.length === 0) return "green";
  if (checks.every((check) => GREEN_STATES.has(check.state))) return "green";
  if (checks.some((check) => RED_STATES.has(check.state))) return "red";
  return "pending";
}

import { defineTool, type ToolDefinition } from "@earendil-works/pi-coding-agent";
import { Type } from "typebox";

/**
 * check_pr_ci (contract v1, spec section 1.4): the standing CI rule as a
 * typed tool. The host resolves the task's PR and reports every check on
 * the head SHA; overall green requires every check completed and
 * successful. The result is recorded per task and powers the emit_card
 * land-gate (G-1). Fails soft: every outcome returns as text.
 */

export const CHECK_PR_CI_TOOL_NAME = "check_pr_ci";

export function createCheckPrCiTool(check: (taskId: string) => Promise<string>): ToolDefinition {
  return defineTool({
    name: CHECK_PR_CI_TOOL_NAME,
    label: "Check PR CI",
    description: [
      "Typed CI status for a task's open PR: every check on the PR head SHA, plus an",
      "overall verdict - green only when every check is completed and successful; one",
      "green job never suffices while others pend or fail. Call it before any land or",
      "merge decision on a direct-pr task: a land decision card is refused without a",
      "fresh green result. Not green: steer the crewmate to fix and re-report.",
    ].join(" "),
    parameters: Type.Object({
      task_id: Type.String({ description: "The task id from crew_status or the context block" }),
    }),
    execute: async (_toolCallId, params) => {
      const text = await check(params.task_id);
      return { content: [{ type: "text", text }], details: {} };
    },
  }) as ToolDefinition;
}

import type { EmittedCard } from "./cardTool";

/**
 * The emit_card boundary lint (contract v1, spec section 4.1): G-1 the CI
 * gate and G-3 the card/voice lint. Each rule turns a prompt rule into a
 * host refusal with corrective text - simultaneously a safety bound and a
 * training signal. A refused card is never shown; the thrown message reaches
 * the model as a loud tool error and it revises.
 *
 * Applies to the FIRSTMATE persona's emit_card only; crewmate cards keep
 * their prompt-steered contract. Pattern seeds are captain-annotatable.
 */

/** How long a green check_pr_ci result stays fresh for the G-1 land gate. */
export const CI_FRESHNESS_MS = 5 * 60_000;

/** Action ids that make a decision card a land/merge offer (G-1). */
const LAND_ACTION_IDS = new Set(["land", "merge", "merge-pr"]);

/** The host-owned settle ids that actually perform a merge in act(). */
const MERGE_ACTION_IDS = new Set(["merge-pr", "land"]);

/**
 * A settle-shaped action id that is not exactly reserved. act() dispatches
 * on the literal id, so "merge-pr55" or "land-it" silently degrades to a
 * steer round-trip and no merge ever runs; the model must be refused rather
 * than left to invent per-PR ids.
 */
const SETTLE_LOOKALIKE = /^(merge[-_ ]?pr|merge|land)([-_ ][a-z0-9]+|\d+)?$/i;

/** The reserved settle ids a lookalike could have meant. */
const RESERVED_SETTLE_IDS = new Set(["merge-pr", "land"]);

/**
 * The first settle-shaped action id that the host would not dispatch, if
 * any. Shared with the crewmate card boundary: both personas render the
 * same footer, and a near-miss id no-ops identically on either.
 */
export function freeformSettleActionId(actions: { id: string }[]): string | undefined {
  return actions.find(
    (action) => SETTLE_LOOKALIKE.test(action.id) && !RESERVED_SETTLE_IDS.has(action.id),
  )?.id;
}

/** The refusal text for a near-miss settle id, shared by both boundaries. */
export function freeformSettleRefusal(actionId: string): string {
  return `action id "${actionId}" is freeform and has no host semantics; use the exact reserved id "merge-pr" to merge a GitHub PR or "land" to merge into the local checkout - any other id is only a steer and merges nothing.`;
}

/** L1 seed list: progress/status card patterns (case-insensitive). */
const PROGRESS_PATTERNS: RegExp[] = [
  /still (pending|running|waiting)/i,
  /watching (the )?(run|ci|checks)/i,
  /no red yet/i,
  /ci is (pending|running)/i,
  /in progress/i,
  /working on it/i,
  /will (report|update)/i,
];

/** L3: a title led by a bare SHA, or that is only "PR <n>". */
const SHA_LEAD = /^[0-9a-f]{7,40}\b/i;
const BARE_PR_TITLE = /^PR\s+#?\d+$/i;

/** L4: emoji (extended pictographics) in decision/note copy. */
const EMOJI = /\p{Extended_Pictographic}/u;

export type CardLintContext = {
  /** The delivery posture of the task a card names, when known. */
  taskDelivery: (taskId: string) => "direct-pr" | "local-only" | undefined;
  /** Whether a green check_pr_ci result at most CI_FRESHNESS_MS old exists. */
  freshGreenCi: (taskId: string) => boolean;
  /** The last known CI state for refusal copy ("red", "never checked", ...). */
  ciStateText: (taskId: string) => string;
  /** Open parked decisions' card ids (the L6 re-ask gate). */
  parkedDecisionIds: () => Set<string>;
  /** Resolve a model-passed stable id to the routable card id. */
  resolveCardId: (stableId: string) => string;
  /**
   * Whether a task id names a record (task-system P1, attach first). Absent
   * = the boundary has no task record to check against.
   */
  taskExists?: (taskId: string) => boolean;
};

/** The P1 attach-first refusal for a note that names no task and asserts nothing. */
export const NOTE_NEEDS_TASK_REFUSAL =
