  async interruptCrewmate(taskId: string, mode: "interrupt" | "cancel"): Promise<void> {
    this.assertNotSupervisionHeld(taskId);
    const task = this.tasks.get(taskId);
    if (!task) {
      const record = this.options.tasks.get(taskId);
      if (!record) throw new Error(`Unknown task "${taskId}".`);
      // Already-finished work must not be relabelled cancelled (idle teardown
      // after a merge, or a second cancel on a delivered row).
      if (record.status === "delivered" || record.status === "done") return;
      if (isResumable(record)) {
        if (mode === "cancel") {
          this.closeRecord(record.id, "cancelled", undefined, "captain");
          this.options.broadcastEvent({
            type: "task_finished",
            taskId,
            status: "cancelled",
            title: record.title,
          });
          this.broadcastCrewCounts();
        }
        return;
      }
      throw new Error(`Task ${taskId} is already ${describeStatus(record)}.`);
    }
    if (mode === "cancel") {
      if (task.state === "idle") {
        this.finish(task, "cancelled");
      } else {
        task.cancelled = true;
        await task.transport?.abort();
      }
      return;
    }
    if (task.state === "streaming" || task.state === "starting") {
      task.interruptRequested = true;
      await task.transport?.abort();
    }
  }

